import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2021_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace missing values with the median NO2_value
median_NO2 = data['NO2_value'].dropna().median()
data['NO2_value'] = data['NO2_value'].fillna(median_NO2)

# Compute neighborhood NO2 values
neighborhood_NO2 = {}
for borough in data['borough'].unique():
    neighbors = adjacency[adjacency['borough'] == borough]['neighbor'].unique()
    neighborhood_NO2[borough] = data[data['borough'].isin(neighbors)]['NO2_value'].mean()

# Compute Moran's I statistic for each borough
moran_I = {}
for borough in data['borough'].unique():
    neighbors = adjacency[adjacency['borough'] == borough]['neighbor'].unique()
    neighborhood_NO2_values = data[data['borough'].isin(neighbors)]['NO2_value']
    moran_I[borough] = np.corrcoef(data[data['borough'] == borough]['NO2_value'], neighborhood_NO2_values)[0, 1]

# Identify hot and cold spots
hot_spots = {}
cold_spots = {}
for borough, value in moran_I.items():
    if data[data['borough'] == borough]['NO2_value'].values[0] > data['NO2_value'].median() and value > 0:
        hot_spots[borough] = value
    elif data[data['borough'] == borough]['NO2_value'].values[0] < data['NO2_value'].median() and value < 0:
        cold_spots[borough] = value

# Test for statistical significance
data_points_used = data['NO2_value'].count()
test_statistic = {}
significance_measure = {}
for borough, value in hot_spots.items():
    neighbors = adjacency[adjacency['borough'] == borough]['neighbor'].unique()
    neighborhood_NO2_values = data[data['borough'].isin(neighbors)]['NO2_value']
    test_statistic[borough] = value
    significance_measure[borough] = np.mean([value for _ in range(500) if np.random.choice(data['NO2_value'].values, size=len(neighbors), replace=True).mean() > data[data['borough'] == borough]['NO2_value'].values[0] and np.corrcoef(data[data['borough'] == borough]['NO2_value'], neighborhood_NO2_values)[0, 1] > 0])

# List identified boroughs
print(f'data_points_used = {data_points_used}')
for borough, value in hot_spots.items():
    print(f'FINAL ANSWER: {borough} (HH, test statistic = {test_statistic[borough]}, significance measure = {significance_measure[borough]})')
for borough, value in cold_spots.items():
    print(f'FINAL ANSWER: {borough} (LL, test statistic = {value}, significance measure = {np.mean([value for _ in range(500) if np.random.choice(data['NO2_value'].values, size=len(neighbors), replace=True).mean() < data[data['borough'] == borough]['NO2_value'].values[0] and np.corrcoef(data[data['borough'] == borough]['NO2_value'], neighborhood_NO2_values)[0, 1] < 0])})')
if not hot_spots and not cold_spots:
    print('FINAL ANSWER: none')
